/** Hand-placed sites in agrar-city-v2.png, in the painting's native 1536x1024 coordinates.
 * Streets and all decorative houses are in that painting, not generated by this module.
 */
export const AGRAR_LANDSCAPE={x:0,y:0,width:1536,height:1024};
const site=(id,x,y,w,h,painted=true)=>({id,x,y,w,h,painted});
export const AGRAR_LANDMARKS={
  questhouse:site('civic-hall',701,468,216,135),
  'produce:grain':site('grain-mill',366,307,292,222),
  'produce:biomass':site('greenhouses',580,234,204,126),
  'produce:food':site('food-mill',715,302,174,124),
  'consume:water':site('water-tanks',906,272,174,140),
  'consume:fertilizer':site('fertilizer-barn',1040,305,155,99),
  'consume:machinery':site('machine-hangar',1245,333,204,130),
  'consume:consumer':site('freight-depot',1184,432,244,126),
  school:site('school-court',329,450,213,117),
  smuggler:site('cellar-hideout',1202,580,163,99),
  'fun:tavern':site('tavern',940,586,206,116),
  'fun:casino':site('games-house',425,557,123,100),
  'fun:fair':site('market-stalls',630,554,141,83),
  'fun:racetrack':site('race-court',1105,508,193,77),
  'fun:mine':site('old-tunnel',155,565,94,90),
  beggar:site('beggar-square',710,604,23,28,false),
  dog:site('dog-square',767,625,29,25,false),
};
// The four staggered courtyards in the southeast extension quarter. Factories replace their plots.
export const AGRAR_WORKSHOPS=[
  site('works-bio-0',1402,684,118,90,false),
  site('works-bio-1',1349,827,147,106,false),
  site('works-bio-2',1145,905,159,108,false),
  site('works-chem-0',1377,969,162,110,false),
];
// Additional commodity services use deliberately inspected dry farm/service yards, never a grid.
export const AGRAR_SERVICES=[
  site('farm-cannery',257,873,105,88,true),
  site('farm-clinic',844,831,87,72,true),
  site('farm-textiles',712,894,118,96,true),
  site('north-farm',661,61,75,51,true),
  site('hill-farm',1241,70,89,59,true),
  site('orchard-office',102,418,78,81,true),
  site('seed-court',350,631,98,76,true),
  site('garden-store',233,550,88,76,true),
  site('west-farm',92,317,103,77,true),
  site('southern-farm',77,916,116,98,true),
  site('field-service',555,373,83,75,true),
  site('northern-service',1435,45,73,42,true),
];
const fixedKey=item=>item.good?item.kind+':'+item.good:item.kind==='fun'?'fun:'+item.building:item.kind;
export function planAgrarCity(entity,items,previous=new Map(),recipeCategory=()=>null){
  const sites=new Map([...Object.values(AGRAR_LANDMARKS),...AGRAR_WORKSHOPS,...AGRAR_SERVICES].map(s=>[s.id,s]));
  const assignments=new Map(),used=new Set(),reservedFactories=new Map();
  const categoryCounts={};
  for(const item of items.filter(it=>it.kind==='factory').sort((a,b)=>(a.index??0)-(b.index??0))){
    const cat=item.cat||recipeCategory(item.recipe)||'bio',index=categoryCounts[cat]||0;categoryCounts[cat]=index+1;
    const s=sites.get(`works-${cat}-${index}`);if(s)reservedFactories.set(item.key,s);
  }
  const choose=item=>{
    const fixed=AGRAR_LANDMARKS[fixedKey(item)];if(fixed)return fixed;
    const factory=reservedFactories.get(item.key);if(factory)return factory;
    if(item.kind==='plot'){const s=sites.get(`works-${item.cat||'bio'}-${item.plotIndex??0}`);if(s)return s;}
    return null;
  };
  for(const item of items){const s=choose(item);if(s&&!used.has(s.id)){assignments.set(item.key,s.id);used.add(s.id);}}
  for(const item of items){
    if(assignments.has(item.key))continue;
    const old=sites.get(previous.get(item.key));if(old&&!used.has(old.id)){assignments.set(item.key,old.id);used.add(old.id);}
  }
  for(const item of [...items].sort((a,b)=>a.key.localeCompare(b.key))){
    if(assignments.has(item.key))continue;
    const s=[...AGRAR_SERVICES,...AGRAR_WORKSHOPS].find(s=>!used.has(s.id));
    if(!s)throw new Error('Keine gestaltete Agrar-Parzelle für '+item.key);
    assignments.set(item.key,s.id);used.add(s.id);
  }
  const records=items.map(item=>{
    const s=sites.get(assignments.get(item.key)),character=item.kind==='dog'||item.kind==='beggar';
    const box={x:s.x-s.w/2,y:s.y-s.h,width:s.w,height:s.h};
    // Clipped roof corners make building targets follow the illustration rather than empty rectangles.
    const polygon=character?null:[{x:box.x+s.w*.18,y:box.y},{x:box.x+s.w*.83,y:box.y},{x:box.x+s.w,y:box.y+s.h*.23},
      {x:box.x+s.w,y:s.y-s.h*.12},{x:box.x+s.w*.78,y:s.y},{x:box.x+s.w*.12,y:s.y},{x:box.x,y:s.y-s.h*.2},{x:box.x,y:box.y+s.h*.25}];
    return {...s,key:item.key,item,character,box,polygon,authored:true};
  });
  return {type:entity.type,authored:true,records,assignments,roads:[],landscape:AGRAR_LANDSCAPE,
    bounds:{x:80,y:25,width:1420,height:975},plaza:{x:739,y:610}};
}
